insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('9d8de611-b2ff-5534-9604-796e4c30582c','walk','Спокойная прогулка','activity','beginner','Идите в темпе, в котором легко говорить.','["Начните с медленного шага", "Держите плечи свободно", "Сократите прогулку при усталости"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Пройти по комнате','Немного удлинить маршрут','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('cede21ad-6937-5381-8ffc-78e43f4e86cc','march','Шаги на месте','activity','beginner','Мягко переносите вес с ноги на ногу.','["Встаньте рядом с опорой", "Поднимайте стопы невысоко", "Не задерживайте дыхание"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Держаться за спинку стула','Добавить спокойные движения рук','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('a76fd4ad-fc54-5a6e-b5cc-2aaba31a222a','chair-squat','Вставание со стула','activity','beginner','Устойчивый стул поставьте к стене.','["Стопы под коленями", "Наклонитесь чуть вперёд и встаньте", "Медленно сядьте"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Помогать руками','Вставать без помощи рук','["none"]'::jsonb,null,true) on conflict (id) do nothing;
